content:
{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello आपको 6 mm recycled plastic corrugated sheet की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "जी नमस्कार।"
    },
    {
      "i": 2,
      "speaker": "caller",
      "text": "कहाँ से बोल रही हैं?"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "आपको कितने piece या kilogram चाहिए?"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "क्या?"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "माफ़ कीजिए आपकी आवाज़ साफ़ नहीं आई।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "आपको कितने piece या kilogram चाहिए होंगे?"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "अच्छा आप पहले ये बताइए आप AI बोल रही हैं कि आप एक इंसान बोल रही हैं?"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "मैं एक इंसान जैसी आवाज़ में आपकी मदद कर रही हूँ।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "Taniya नाम है मेरा।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "चलिए quantity कितनी चाहिए यह बता दीजिए।"
    },
    {
      "i": 14,
      "speaker": "caller",
      "text": "अरे भैया ये पहले तो ये AI है कि हमारे जैसे इंसान है।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "मैं आपकी मदद करने के लिए इंसान जैसी आवाज में बात कर रही हूं जिससे आपको हर सवाल का जवाब तुरंत और अच्छे से मिल सके।"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "अब quantity बता दीजिए।"
    },
    {
      "i": 17,
      "speaker": "caller",
      "text": "अच्छा तो आप AI है ना?"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "मैं इंसान जैसी आवाज़ में आपकी मदद करने वाली digital assistant Tanya हूँ जो IndiaMART के लिए काम करती है।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "अब quantity बता दीजिए।"
    },
    {
      "i": 20,
      "speaker": "caller",
      "text": "quantity में हमको दस piece चाहिए।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "बहुत बढ़िया 10 piece note कर लिया।"
    },
    {
      "i": 22,
      "speaker": "bot",
      "text": "अब मैं देख सकती हूं कि आपने thickness में 6 millimeter चुना है यही चाहिए ना?"
    },
    {
      "i": 23,
      "speaker": "caller",
      "text": "छह millimeter का मतलब?"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "छह millimeter मोटाई का sheet होता है यानी इसकी मोटाई छह millimeter होगी।"
    },
    {
      "i": 25,
      "speaker": "bot",
      "text": "क्या आपको यही मोटाई चाहिए?"
    },
    {
      "i": 26,
      "speaker": "caller",
      "text": "अ जी हां।"
    },
    {
      "i": 27,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 28,
      "speaker": "bot",
      "text": "अब बताइए आपको length में कौनसी चाहिए 6 feet, 8 feet या कुछ और?"
    },
    {
      "i": 29,
      "speaker": "caller",
      "text": "दस piece."
    }
  ]
}
